companionBundle.script:
const root = document.getElementById('app');

root.innerHTML = `
  <main class="browser-shell">
    <form class="address-row" id="address-form">
      <button type="button" class="icon" id="back" aria-label="Zurück">‹</button>
      <button type="button" class="icon" id="forward" aria-label="Vor">›</button>
      <button type="button" class="icon" id="reload" aria-label="Neu laden">↻</button>
      <input id="address" inputmode="url" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Adresse oder Suche" />
      <button class="go" aria-label="Öffnen">Los</button>
    </form>
    <section class="viewport" id="viewport">
      <img id="screen" alt="Ansicht des Browsers auf dem PC" draggable="false" />
      <div class="empty" id="empty">
        <div class="pulse"></div>
        <strong>Browser auf deinem PC</strong>
        <span id="status">wird verbunden …</span>
      </div>
    </section>
    <footer class="tool-row">
      <button type="button" id="keyboard">⌨ <span>Tastatur</span></button>
      <button type="button" id="paste">Einfügen</button>
      <button type="button" id="copy">Auswahl kopieren</button>
      <span class="live" id="live">PC</span>
    </footer>
    <textarea id="key-input" aria-label="Text in den PC-Browser eingeben" autocapitalize="sentences" autocomplete="off"></textarea>
  </main>
`;

const address = document.getElementById('address');
const screen = document.getElementById('screen');
const empty = document.getElementById('empty');
const status = document.getElementById('status');
const live = document.getElementById('live');
const keyInput = document.getElementById('key-input');
let latest = null;
let stopped = false;
let drag = null;
let typedTail = Promise.resolve();
let actionTail = Promise.resolve();

function normalizedUrl(value) {
  const clean = value.trim();
  if (!clean) return null;
  if (/^https?:\/\//i.test(clean)) return clean;
  if (/^[a-z0-9.-]+\.[a-z]{2,}(?:[/:?#]|$)/i.test(clean)) return `https://${clean}`;
  return `https://www.google.com/search?q=${encodeURIComponent(clean)}`;
}

function applySnapshot(snapshot) {
  if (!snapshot || typeof snapshot.image !== 'string') return;
  latest = snapshot;
  screen.src = `data:${snapshot.mimeType || 'image/jpeg'};base64,${snapshot.image}`;
  screen.classList.add('ready');
  empty.classList.add('hidden');
  if (document.activeElement !== address && typeof snapshot.url === 'string' && snapshot.url !== 'about:blank') {
    address.value = snapshot.url;
  }
  document.getElementById('back').disabled = !snapshot.canGoBack;
  document.getElementById('forward').disabled = !snapshot.canGoForward;
  live.textContent = 'PC · live';
  live.classList.add('online');
}

async function perform(actionId, input) {
  if (stopped) return null;
  live.textContent = 'PC · …';
  try {
    const snapshot = await teydra.query(actionId, input);
    applySnapshot(snapshot);
    return snapshot;
  } catch (error) {
    live.textContent = 'PC · getrennt';
    live.classList.remove('online');
    status.textContent = error instanceof Error ? error.message : 'Der PC antwortet nicht.';
    empty.classList.remove('hidden');
    return null;
  }
}

function act(actionId, input) {
  const result = actionTail.then(() => perform(actionId, input));
  actionTail = result.then(() => undefined, () => undefined);
  return result;
}

async function poll() {
  if (stopped) return;
  await act(latest ? 'browser.snapshot' : 'browser.start');
  setTimeout(poll, latest ? 850 : 1_500);
}

document.getElementById('address-form').addEventListener('submit', async (event) => {
  event.preventDefault();
  const url = normalizedUrl(address.value);
  if (!url) return;
  address.blur();
  await act('browser.navigate', { url });
});

for (const [id, actionId] of [
  ['back', 'browser.back'],
  ['forward', 'browser.forward'],
  ['reload', 'browser.reload'],
]) document.getElementById(id).addEventListener('click', () => act(actionId));

screen.addEventListener('pointerdown', (event) => {
  screen.setPointerCapture(event.pointerId);
  drag = { id: event.pointerId, x: event.clientX, y: event.clientY, moved: false };
});
screen.addEventListener('pointermove', (event) => {
  if (!drag || drag.id !== event.pointerId) return;
  if (Math.abs(event.clientX - drag.x) + Math.abs(event.clientY - drag.y) > 12) drag.moved = true;
});
screen.addEventListener('pointerup', async (event) => {
  if (!drag || drag.id !== event.pointerId || !latest) return;
  const start = drag;
  drag = null;
  const box = screen.getBoundingClientRect();
  const x = Math.max(0, Math.min(latest.width, (event.clientX - box.left) / box.width * latest.width));
  const y = Math.max(0, Math.min(latest.height, (event.clientY - box.top) / box.height * latest.height));
  if (start.moved) {
    await act('browser.scroll', {
      x, y,
      deltaX: (start.x - event.clientX) * 2,
      deltaY: (start.y - event.clientY) * 2,
    });
  } else {
    await act('browser.pointer', { x, y });
  }
});

document.getElementById('keyboard').addEventListener('click', () => keyInput.focus());
document.getElementById('paste').addEventListener('click', async () => {
  try {
    const text = await teydra.clipboard.read();
    if (text) await act('browser.type', { text });
  } catch (error) {
    status.textContent = error instanceof Error ? error.message : 'Einfügen wurde nicht erlaubt.';
  }
});
document.getElementById('copy').addEventListener('click', async () => {
  try {
    const snapshot = await act('browser.snapshot');
    if (!snapshot?.selection) throw new Error('Im Browser ist kein Text ausgewählt.');
    await teydra.clipboard.write(snapshot.selection);
  } catch (error) {
    status.textContent = error instanceof Error ? error.message : 'Kopieren wurde nicht erlaubt.';
  }
});

keyInput.addEventListener('input', () => {
  const text = keyInput.value;
  keyInput.value = '';
  if (!text) return;
  typedTail = typedTail.then(() => act('browser.type', { text }));
});
keyInput.addEventListener('keydown', (event) => {
  if (!['Enter', 'Backspace', 'Tab', 'Escape', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(event.key)) return;
  event.preventDefault();
  typedTail = typedTail.then(() => act('browser.key', { key: event.key }));
});

window.addEventListener('beforeunload', () => { stopped = true; });
teydra.ready(poll);

companionBundle.style:
:root {
  color-scheme: dark;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #0b0d0d;
  color: #f5f7f6;
}

* { box-sizing: border-box; }
html, body, #app { width: 100%; height: 100%; margin: 0; overflow: hidden; }
button, input, textarea { font: inherit; }
button { color: inherit; }
.browser-shell { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; background: #0b0d0d; }
.address-row { display: grid; grid-template-columns: 34px 34px 34px minmax(0, 1fr) auto; gap: 5px; padding: 8px; border-bottom: 1px solid #24302c; background: #101514; }
.address-row button, .tool-row button { appearance: none; border: 1px solid #2b3935; border-radius: 11px; background: #19211f; min-height: 38px; }
.address-row button:active, .tool-row button:active { background: #25312e; transform: scale(.97); }
.address-row button:disabled { opacity: .3; }
.address-row .icon { font-size: 24px; line-height: 1; }
.address-row .go { padding: 0 11px; color: #9ee7cf; font-size: 12px; font-weight: 750; }
#address { width: 100%; min-width: 0; border: 1px solid #2b3935; border-radius: 12px; outline: none; padding: 0 11px; background: #080b0a; color: #edf5f2; font-size: 13px; }
#address:focus { border-color: #40b995; box-shadow: 0 0 0 2px #174638; }
.viewport { position: relative; min-height: 0; display: grid; place-items: center; overflow: hidden; background: #171a19; touch-action: none; }
#screen { display: none; width: 100%; height: 100%; object-fit: contain; object-position: top center; user-select: none; -webkit-user-select: none; }
#screen.ready { display: block; }
.empty { position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 9px; padding: 30px; color: #e8efed; text-align: center; background: radial-gradient(circle at 50% 43%, #17241f, #0d1110 55%); }
.empty.hidden { display: none; }
.empty span { max-width: 280px; color: #8d9d98; font-size: 13px; line-height: 1.45; }
.pulse { width: 38px; height: 38px; margin-bottom: 7px; border: 2px solid #2b6d59; border-top-color: #70dfbd; border-radius: 50%; animation: turn 1s linear infinite; }
.tool-row { min-height: 52px; display: flex; align-items: center; gap: 6px; padding: 7px 9px calc(7px + env(safe-area-inset-bottom)); border-top: 1px solid #24302c; background: #101514; }
.tool-row button { padding: 0 10px; color: #dbe6e2; font-size: 11px; font-weight: 650; }
.live { margin-left: auto; color: #8d9d98; font-size: 10px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; white-space: nowrap; }
.live.online { color: #70dfbd; }
#key-input { position: fixed; left: 50%; bottom: 1px; width: 2px; height: 2px; opacity: .01; resize: none; }
@keyframes turn { to { transform: rotate(360deg); } }

@media (max-width: 360px) {
  .tool-row button { padding: 0 7px; }
  .tool-row button span { display: none; }
}
